<?php
define('CSRFCHECK_WITH_TOKEN',1);require $_SERVER['DOCUMENT_ROOT'].'/main.inc.php';require_once __DIR__.'/../lib/main.lib.php';require_once __DIR__.'/../class/OperationsService.class.php';cpo_require($user,'read');$langs->load('chinaplanetoperations@chinaplanetoperations');$service=new OperationsService($db);$operationId=GETPOSTINT('operation_id');$action=GETPOST('action','aZ09');
if($action==='move'){cpo_require($user,'task_write');try{$service->moveTask(GETPOSTINT('task_id'),GETPOST('status','alphanohtml'),(int)$user->id);setEventMessages($langs->trans('TaskUpdated'),null,'mesgs');}catch(Throwable $e){setEventMessages($e->getMessage(),null,'errors');}}
$tasks=$service->tasks($operationId);$columns=OperationsService::taskStatuses();$morecss=array(cpo_asset('/custom/chinaplanetoperations/css/operations.css'));llxHeader('',$langs->trans('InternalTaskBoard'),'','',0,0,array(),$morecss);
?><main class="cpo-page"><section class="cpo-hero"><div><span class="cpo-eyebrow">DAILY INTERNAL WORK</span><h1><?php echo $langs->trans('InternalTaskBoard'); ?></h1><p><?php echo $langs->trans('TaskBoardHelp'); ?></p></div><a class="button" href="../operations/index.php"><?php echo $langs->trans('OperationsRegister'); ?></a></section><section class="cpo-kanban"><?php foreach($columns as $status=>$progress){ ?><div class="cpo-kanban-column"><header><strong><?php echo $langs->trans('TaskStatus_'.$status); ?></strong><span><?php echo count(array_filter($tasks,function($t)use($status){return $t['status']===$status;})); ?></span></header><?php foreach($tasks as $task)if($task['status']===$status){ ?><article class="priority-<?php echo dol_escape_htmltag($task['priority']); ?>"><small><?php echo dol_escape_htmltag($task['ref']); ?></small><h3><?php echo dol_escape_htmltag($task['title']); ?></h3><?php if($task['operation_ref']){ ?><a href="../operations/view.php?id=<?php echo (int)$task['fk_operation']; ?>"><?php echo dol_escape_htmltag($task['operation_ref']); ?></a><?php } ?><p><?php echo dol_escape_htmltag($task['owner_login']?:$langs->trans('Unassigned')); ?></p><time><?php echo dol_escape_htmltag($task['date_deadline']?:'—'); ?></time><?php if(cpo_can($user,'task_write')){ ?><form method="post"><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="action" value="move"><input type="hidden" name="task_id" value="<?php echo (int)$task['rowid']; ?>"><input type="hidden" name="operation_id" value="<?php echo $operationId; ?>"><select name="status" onchange="this.form.submit()"><?php foreach($columns as $target=>$x){ ?><option value="<?php echo $target; ?>"<?php echo $target===$status?' selected':''; ?>><?php echo $langs->trans('TaskStatus_'.$target); ?></option><?php } ?></select></form><?php } ?></article><?php } ?></div><?php } ?></section></main><?php llxFooter();$db->close(); ?>
